// Large authored BSPs can be close enough to the Vita3K guest heap limit that
// even a diagnostic printf after a source compaction pass can fault inside the
// guest syscall shim. Keep the compaction itself observable from the caller,
// but allow that caller to suppress per-pass logging until the heap is stable.
bool gSuppressScalarStageLogging = false;
bool gMapUsesTexturePaging = false; // Source-owned during map loading only.

kisak::vita::VitaPackLayoutError InstalledPackLayout(const char* path,uint32_t mapIndex) {
#if defined(__vita__) && KISAK_VITA_CPU_RUNTIME
    // Freeze expected metadata in app0, independently of the installed packs.
    // Do not scan any payload here: startup remains catalog/common-only.
    static std::array<uint8_t,16+17*48+1> expected{};
    static size_t expectedSize=0;
    static bool attempted=false;
    if(!attempted) {
        attempted=true;
        if(FILE* input=std::fopen("app0:cpu-pack-layout.bin","rb")) {
            expectedSize=std::fread(expected.data(),1,expected.size(),input);
            std::fclose(input);
        }
    }
    FILE* input=path?std::fopen(path,"rb"):nullptr;
    uint64_t size=0;uint32_t crc=0;
    const auto result=kisak::vita::VitaPackLayoutProbeFile(expected.data(),expectedSize,mapIndex,input,&size,&crc);
    if(input)std::fclose(input);
    char detail[128]{};
    std::snprintf(detail,sizeof(detail),"map=%u bytes=%llu headerTocCrc=%08x status=%s",
        unsigned(mapIndex),static_cast<unsigned long long>(size),crc,kisak::vita::VitaPackLayoutErrorName(result));
    kisak::vita::VitaScriptServicesTrace("vita_installed_pack_layout",path,detail);
    return result;
#else
    (void)path;(void)mapIndex;return kisak::vita::VitaPackLayoutError::Ok;
#endif
}
